def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o

    if len(mapping) != len(set(mapping.values())):
        return "Failed"

    decoded = []
    for char in message:
        if char in mapping:
            decoded.append(mapping[char])
        else:
            decoded.append(char)

    return ''.join(decoded)
