def count_sequences(n: int, last: int, memo: dict) -> int:
    if last < n:
        return 0

    if last in memo:
        return memo[last]

    count = 1
    for i in range(n // 2, 0, -1):
        count += count_sequences(n, i, memo)

    memo[last] = count
    return count
